CREATE TABLE IF NOT EXISTS member_learning_paths(id bigserial PRIMARY KEY,slug text NOT NULL UNIQUE,title text NOT NULL,description text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','published','archived')),sort_order integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS member_learning_path_courses(path_id bigint NOT NULL REFERENCES member_learning_paths(id) ON DELETE CASCADE,course_id bigint NOT NULL REFERENCES member_courses(id) ON DELETE CASCADE,sort_order integer NOT NULL DEFAULT 0,PRIMARY KEY(path_id,course_id),UNIQUE(path_id,sort_order));
CREATE TABLE IF NOT EXISTS member_course_prerequisites(course_id bigint NOT NULL REFERENCES member_courses(id) ON DELETE CASCADE,prerequisite_course_id bigint NOT NULL REFERENCES member_courses(id) ON DELETE CASCADE,PRIMARY KEY(course_id,prerequisite_course_id),CHECK(course_id<>prerequisite_course_id));
CREATE TABLE IF NOT EXISTS member_badges(id bigserial PRIMARY KEY,slug text NOT NULL UNIQUE,title text NOT NULL,description text NOT NULL DEFAULT '',course_id bigint REFERENCES member_courses(id) ON DELETE CASCADE,enabled boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS member_badge_awards(id bigserial PRIMARY KEY,badge_id bigint NOT NULL REFERENCES member_badges(id) ON DELETE CASCADE,member_id bigint NOT NULL REFERENCES member_accounts(id) ON DELETE CASCADE,awarded_at timestamptz NOT NULL DEFAULT now(),UNIQUE(badge_id,member_id));
CREATE TABLE IF NOT EXISTS member_content_reports(id bigserial PRIMARY KEY,member_id bigint NOT NULL REFERENCES member_accounts(id) ON DELETE CASCADE,artwork_id bigint NOT NULL REFERENCES member_artworks(id) ON DELETE CASCADE,reason text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','resolved','dismissed')),resolved_by text,resolved_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(member_id,artwork_id));
CREATE INDEX IF NOT EXISTS member_content_reports_queue ON member_content_reports(status,created_at);
